template.solver:
def solve(n):
    if n % 2 != 0:
        return 0
    total = n * (n + 1) // 2
    if total % 2 != 0:
        return 0
    half = total // 2
    k = n // 2
    dp = [[0] * (half + 1) for _ in range(k + 1)]
    dp[0][0] = 1
    for x in range(1, n + 1):
        for j in range(k, 0, -1):
            for s in range(half, x - 1, -1):
                dp[j][s] += dp[j - 1][s - x]
    return dp[k][half] * factorial(k) * factorial(k)
